def solve(df):
    return (
        df.group_by("category")
        .agg(
            pl.len().alias("n"),
            pl.col("value").mean().alias("avg"),
        )
        .sort("avg", descending=True)
    )

def solve(df):
    return df.group_by("product").agg(
        pl.col("qty").sum(),
        pl.col("revenue").sum(),
    )

def solve(df):
    return df.group_by("team").agg(
        pl.col("score").min().alias("lo"),
        pl.col("score").max().alias("hi"),
    )

def solve(df):
    return df.group_by("product").agg(
        ((pl.col("price") * pl.col("qty")).sum() / pl.col("qty").sum()).alias("wavg")
    )

def solve(orders, customers):
    return (
        orders.join(customers, on="customer_id", how="inner")
        .select("order_id", "customer_name", "amount")
    )

def solve(sales, products):
    return sales.join(products, on="product", how="inner").select(
        "sale_id", "product", "price"
    )

def solve(employees, depts):
    return employees.join(depts, on="dept_id", how="left").select(
        "name", "dept_name"
    )

def solve(orders, customers):
    return orders.join(
        customers, left_on="cust", right_on="id", how="inner"
    ).select("order_id", "name")

def solve(customers, orders):
    return customers.join(
        orders, left_on="id", right_on="customer_id", how="anti"
    )

def solve(jan, feb):
    return jan.join(feb, on="product", how="full", coalesce=True).select(
        "product", "jan", "feb"
    )

def solve(items, prices):
    return (
        items.join(prices, on="product", how="inner")
        .with_columns((pl.col("qty") * pl.col("price")).alias("revenue"))
        .select("product", "revenue")
    )

def solve(orders, customers):
    return (
        orders.join(customers, on="customer_id", how="inner")
        .group_by("city")
        .agg(pl.col("amount").sum())
    )

def solve(emp):
    managers = emp.select(
        pl.col("id").alias("manager_id"),
        pl.col("name").alias("manager"),
    )
    return emp.join(managers, on="manager_id", how="left").select("name", "manager")

def solve(items, prices):
    return items.join(prices, on="item", how="left").with_columns(
        pl.col("price").fill_null(0)
    )

def solve(df):
    return df.with_columns(
        pl.col("salary")
        .rank(method="dense", descending=True)
        .over("dept")
        .cast(pl.UInt32)
        .alias("rank_in_dept")
    )

def solve(df):
    return df.filter(
        pl.col("value").rank(method="ordinal", descending=True).over("category") <= 2
    )

def solve(orders, products):
    return (
        orders.join(products, on="product", how="inner")
        .select("order_id", "price")
        .collect()
    )

def solve(sales, regions):
    return (
        sales.join(regions, on="store", how="inner")
        .group_by("region")
        .agg(pl.col("amount").sum())
        .sort("region")
        .collect()
    )

def solve(df):
    return df.with_columns(
        pl.col("path").str.replace_all("/", "-", literal=True)
    )

def solve(df):
    return df.with_columns(
        pl.concat_str(["first", "last"], separator=" ").alias("full_name")
    )

